import{_ as a,o,c as i,a2 as t}from"./chunks/framework.mRCPFc5l.js";const c=JSON.parse('{"title":"Packaging & Publishing","description":"","frontmatter":{"title":"Packaging & Publishing","order":22},"headers":[],"relativePath":"learn/mod/publish.md","filePath":"learn/mod/publish.md","lastUpdated":1786957039000}'),l={name:"learn/mod/publish.md"};function s(r,e,n,d,u,h){return o(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="packaging-publishing" tabindex="-1">Packaging &amp; Publishing <a class="header-anchor" href="#packaging-publishing" aria-label="Permalink to &quot;Packaging &amp; Publishing&quot;">​</a></h1><p>After writing your code, package and publish your Mod so more players can use it. Please read the <a href="./guidelines">Development Guidelines</a> before publishing.</p><h2 id="_1-verify-info-json" tabindex="-1">1. Verify Info.json <a class="header-anchor" href="#_1-verify-info-json" aria-label="Permalink to &quot;1. Verify Info.json&quot;">​</a></h2><p><code>Info.json</code> is the Mod info file UMM reads — it was already written in <a href="./first-mod">Minimal Example</a>. Before publishing, double-check <code>EntryMethod</code>, <code>AssemblyName</code>, and <code>Version</code>.</p><h2 id="_2-compile-deploy" tabindex="-1">2. Compile &amp; Deploy <a class="header-anchor" href="#_2-compile-deploy" aria-label="Permalink to &quot;2. Compile &amp; Deploy&quot;">​</a></h2><p>The template supports auto-deploy: after building, the output is placed in the game&#39;s Mods folder, ready for in-game testing.</p><p>For manual deployment, place the compiled output in:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ADOFAI/Mods/MyFirstMod/</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>The release package should include:</p><ul><li><code>MyFirstMod.dll</code> (compiled output)</li><li><code>Info.json</code></li><li>Usage instructions (README)</li><li>Other dependency DLLs (if any)</li></ul><h2 id="_3-publish-to-github-release" tabindex="-1">3. Publish to GitHub Release <a class="header-anchor" href="#_3-publish-to-github-release" aria-label="Permalink to &quot;3. Publish to GitHub Release&quot;">​</a></h2><ol><li>Push your code to your GitHub repository</li><li>Create a <strong>Release</strong> on the repository page</li><li>Upload the compiled DLL and usage instructions</li></ol><blockquote><p>Common pitfall: players may mistakenly download the &quot;source code zip&quot; and fail to load it. Always upload compiled artifacts to the Release.</p></blockquote><h2 id="_4-share-on-mod-platforms" tabindex="-1">4. Share on Mod Platforms <a class="header-anchor" href="#_4-share-on-mod-platforms" aria-label="Permalink to &quot;4. Share on Mod Platforms&quot;">​</a></h2><p>You can also publish on the organization&#39;s Mod platform <a href="https://modrift.org" target="_blank" rel="noreferrer">modrift.org</a> to help more players discover your work.</p><h2 id="_5-auto-build-with-github-actions" tabindex="-1">5. Auto-Build with GitHub Actions <a class="header-anchor" href="#_5-auto-build-with-github-actions" aria-label="Permalink to &quot;5. Auto-Build with GitHub Actions&quot;">​</a></h2><p>Manually compiling, packaging, and uploading Releases is tedious. You can use GitHub Actions to automate this on push — see <a href="./github-actions">GitHub Actions Auto Build</a>.</p><h2 id="what-you-learned" tabindex="-1">What You Learned <a class="header-anchor" href="#what-you-learned" aria-label="Permalink to &quot;What You Learned&quot;">​</a></h2><ul><li>What files the release package should contain</li><li>Publishing Mods via GitHub Release</li><li>Entry point for auto-build</li></ul><h2 id="series-complete-🎉" tabindex="-1">Series Complete 🎉 <a class="header-anchor" href="#series-complete-🎉" aria-label="Permalink to &quot;Series Complete 🎉&quot;">​</a></h2><p>You&#39;ve completed the full ADOFAI Mod development workflow. Next, you can:</p><ul><li>Explore the <a href="./../../libs/">Library Docs</a> to process level files with code</li><li>Try the <a href="./../../mods/online-tools/">Online Tools</a>, or contribute your Mod tutorials to the <a href="./../../mods/">User Guide</a></li></ul>',22)])])}const m=a(l,[["render",s]]);export{c as __pageData,m as default};
